#include <iostream>
#include <string>
#include <string_view>

class Employee {
public:
    Employee(std::string_view first, std::string_view last, std::string_view ssn)
        : firstName(first), lastName(last), socialSecurityNumber(ssn) {}

    virtual ~Employee() = default;

    void setFirstName(std::string_view first) { firstName = first; }
    std::string getFirstName() const { return firstName; }

    void setLastName(std::string_view last) { lastName = last; }
    std::string getLastName() const { return lastName; }

    void setSocialSecurityNumber(std::string_view ssn) { socialSecurityNumber = ssn; }
    std::string getSocialSecurityNumber() const { return socialSecurityNumber; }

    // Pure virtual function
    virtual double earnings() const = 0;

    // Virtual function with baseline implementation
    virtual void print() const {
        std::cout << getFirstName() << ' ' << getLastName()
                  << "\nsocial security number: " << getSocialSecurityNumber();
    }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
};

class DummyEmployee : public Employee {
public:
    DummyEmployee(std::string_view first, std::string_view last, std::string_view ssn)
        : Employee(first, last, ssn) {}

    double earnings() const override { return 0.0; }
};

int main() {
    DummyEmployee emp("John", "Smith", "111-11-1111");
    Employee* ptr = &emp;
    ptr->print();
    std::cout << "\nearnings: $" << ptr->earnings() << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <string_view>
#include <stdexcept>
#include <iomanip>

class Employee {
public:
    Employee(std::string_view first, std::string_view last, std::string_view ssn)
        : firstName(first), lastName(last), socialSecurityNumber(ssn) {}

    virtual ~Employee() = default;

    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }
    std::string getSocialSecurityNumber() const { return socialSecurityNumber; }

    virtual double earnings() const = 0;

    virtual void print() const {
        std::cout << getFirstName() << ' ' << getLastName()
                  << "\nsocial security number: " << getSocialSecurityNumber();
    }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
};

class SalariedEmployee : public Employee {
public:
    SalariedEmployee(std::string_view first, std::string_view last,
                     std::string_view ssn, double salary = 0.0)
        : Employee(first, last, ssn) {
        setWeeklySalary(salary);
    }

    void setWeeklySalary(double salary) {
        if (salary >= 0.0) {
            weeklySalary = salary;
        } else {
            throw std::invalid_argument("Weekly salary must be >= 0.0");
        }
    }

    double getWeeklySalary() const { return weeklySalary; }

    double earnings() const override {
        return getWeeklySalary();
    }

    void print() const override {
        std::cout << "salaried employee: ";
        Employee::print(); // explicitly reuse base-class version
        std::cout << "\nweekly salary: " << getWeeklySalary();
    }

private:
    double weeklySalary{0.0};
};

int main() {
    std::cout << std::fixed << std::setprecision(2);
    SalariedEmployee salaried("John", "Smith", "111-11-1111", 800.00);

    Employee* employeePtr = &salaried;
    employeePtr->print();
    std::cout << "\nearnings: $" << employeePtr->earnings() << "\n";
    return 0;
}
